import{post}from"/js/modules/Ajax.js";export const EditorActionType=Object.freeze({LOAD_SIDE_PANEL:"LOAD_SIDE_PANEL",TOGGLE_VALUE:"TOGGLE_VALUE",TOGGLE_FAVORITE:"TOGGLE_FAVORITE",DELETE_ARTICLE:"DELETE_ARTICLE",OPEN_MODAL:"OPEN_MODAL"});const pending_toggles=new Set;function toggleKey(e,t){return`${e}:${t}`}export function isTogglePending(e,t){return pending_toggles.has(toggleKey(e,t))}export async function runToggle(e,t,o){const n=toggleKey(e,t);pending_toggles.add(n);try{return await o()}finally{pending_toggles.delete(n)}}export function extractParamsFromDataset(e){const t={};const o="glpiKbActionParam";for(const[n,r]of Object.entries(e)){if(n.startsWith(o)){const e=n.slice(o.length).toLowerCase();t[e]=r}}return t}export async function toggleFavorite(e,t){const o=await post(`Knowbase/${e}/ToggleFavorite`,{value:t});return o.json()}export function toggleField(e,t,o){return post(`Knowbase/${e}/ToggleField`,{field:t,value:o})}export function deleteArticle(e){return post(`Knowbase/KnowbaseItem/${e}/Delete`,{},[409])}export function syncToggleCheckboxes(e,t,o,n=null){let r=`[data-glpi-kb-action="${CSS.escape(t)}"][data-glpi-kb-action-param-id="${CSS.escape(e)}"]`;if(n!==null){r+=`[data-glpi-kb-action-param-field="${CSS.escape(n)}"]`}for(const e of document.querySelectorAll(r)){const t=e.querySelector('input[type="checkbox"]');if(t){t.checked=o}}}